return document.GetWarnings().Select(w=>new{text=w.GetDescriptionText(),elements=w.GetFailingElements().Select(id=>new{id=id.Value,name=document.GetElement(id).Name,category=document.GetElement(id).Category==null?"":document.GetElement(id).Category.Name,typeMark=document.GetElement(id).get_Parameter(BuiltInParameter.ALL_MODEL_TYPE_MARK)==null?"":document.GetElement(id).get_Parameter(BuiltInParameter.ALL_MODEL_TYPE_MARK).AsString()}).ToArray()}).ToArray();
